import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= x <= 255, 0 <= k <= 7).

    The bits shifted out of the high end wrap around to the low end, so the
    result is always in the range 0 to 255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0b10000001, 1, 0b00000011),
        (0x80, 1, 0x01),
        (0x01, 7, 0x80),
        (0xB1, 4, 0x1B),
        (0x00, 3, 0x00),
        (0xFF, 5, 0xFF),
        (0x5A, 0, 0x5A),
    ],
)
def test_rotl8_examples(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected


def test_rotl8_zero_shift_is_identity() -> None:
    for x in range(256):
        assert rotl8(x, 0) == x


def test_rotl8_matches_reference_and_stays_in_range() -> None:
    for x in range(256):
        for k in range(8):
            expected = ((x << k) | (x >> (8 - k))) & 0xFF
            result = rotl8(x, k)
            assert 0 <= result <= 255
            assert result == expected


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x


def test_rotl8_composes() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()
